# CPU Upgrade Path - compatibility / bottleneck checker
# Edit YOUR BUILD, then: python checker.py
BUILD = {
    "cpu": {"socket": "AM4", "tdp_w": 65, "pcie": "4.0"},
    "gpu": {"length_mm": 240, "tdp_w": 200, "power_pins": "1x8pin", "pcie": "4.0"},
    "ram": {"type": "DDR4", "sticks": 2, "gb_each": 8, "mhz": 3200},
    "psu": {"watts": 550, "rating": "Bronze"},
    "case_max_gpu_mm": 320,
    "motherboard": {"socket": "AM4", "ram_type": "DDR4", "m2_slots": 1},
}
NEW_PART = {
    "kind": 'cpu',
    "socket": 'AM5',
    "tdp_w": 105,
}

def check():
    errs, warns = [], []
    # socket match
    if "socket" in NEW_PART and NEW_PART["socket"] != BUILD["motherboard"]["socket"]:
        errs.append(f"Socket mismatch: part is {NEW_PART['socket']}, board is {BUILD['motherboard']['socket']}")
    # ram type match
    if NEW_PART.get("kind") == "ram" and NEW_PART["type"] != BUILD["motherboard"]["ram_type"]:
        errs.append(f"RAM type mismatch: part is {NEW_PART['type']}, board takes {BUILD['motherboard']['ram_type']}")
    # gpu fit
    if NEW_PART.get("kind") == "gpu":
        if NEW_PART["length_mm"] > BUILD["case_max_gpu_mm"]:
            errs.append(f"GPU too long: {NEW_PART['length_mm']}mm > case {BUILD['case_max_gpu_mm']}mm")
        total = BUILD["cpu"]["tdp_w"] + NEW_PART["tdp_w"] + 150
        if total > BUILD["psu"]["watts"]:
            warns.append(f"PSU tight: est. {total}W load vs {BUILD['psu']['watts']}W PSU (want 40%+ headroom)")
        elif total * 1.4 > BUILD["psu"]["watts"]:
            warns.append(f"PSU headroom under 40%: est. {total}W load on {BUILD['psu']['watts']}W PSU")
    # psu headroom for cpu upgrades
    if NEW_PART.get("kind") == "cpu":
        total = NEW_PART["tdp_w"] + BUILD["gpu"]["tdp_w"] + 150
        if total * 1.4 > BUILD["psu"]["watts"]:
            warns.append(f"PSU may be small for this CPU: est. {total}W system load")
    print("ERRORS:" if errs else "No compatibility errors.")
    for e in errs: print("  X", e)
    for w in warns: print("  !", w)
    if not errs and not warns: print("All checks passed.")

check()

